import{_ as d,o as s,c as o,a2 as r,j as t,a as n,t as i}from"./chunks/framework.Buc7gXeZ.js";const p=JSON.parse('{"title":"Blocktypen","description":"Alle Blöcke, die in ApptiveGrid-Seiten zur Verfügung stehen, mit Einstellungen.","frontmatter":{"title":"Blocktypen","description":"Alle Blöcke, die in ApptiveGrid-Seiten zur Verfügung stehen, mit Einstellungen."},"headers":[],"relativePath":"referenz/blocktypen.md","filePath":"referenz/blocktypen.md","lastUpdated":1786170655000}'),l={name:"referenz/blocktypen.md"};function h(a,e,g,m,u,c){return s(),o("div",null,[e[5]||(e[5]=r('<h1 id="blocktypen-—-referenz" tabindex="-1">Blocktypen — Referenz <a class="header-anchor" href="#blocktypen-—-referenz" aria-label="Permalink to &quot;Blocktypen — Referenz&quot;">​</a></h1><p>Die Blockauswahl gliedert sich in drei Gruppen. Diese Referenz folgt derselben Reihenfolge.</p><hr><h2 id="basis-blocke" tabindex="-1">Basis-Blöcke <a class="header-anchor" href="#basis-blocke" aria-label="Permalink to &quot;Basis-Blöcke&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Absatz</strong></td><td><em>Schreibe normalen Text</em></td></tr><tr><td><strong>Überschrift 1</strong></td><td><em>Große Überschrift</em></td></tr><tr><td><strong>Überschrift 2</strong></td><td><em>Mittlere Überschrift</em></td></tr><tr><td><strong>Überschrift 3</strong></td><td><em>Kleine Überschrift</em></td></tr><tr><td><strong>Seite</strong></td><td><em>Eine Unterseite hinzufügen</em></td></tr><tr><td><strong>Horizontales Layout</strong></td><td><em>Blocks nebeneinander anordnen</em></td></tr><tr><td><strong>Vertikales Layout</strong></td><td><em>Blocks untereinander anordnen</em></td></tr><tr><td><strong>Tab-Layout</strong></td><td><em>Unterseiten als Tabs anzeigen</em></td></tr><tr><td><strong>Stepper-Layout</strong></td><td><em>Unterseiten als Schritte anzeigen</em></td></tr><tr><td><strong>Bild</strong></td><td><em>Fügen Sie ein Bild mit benutzerdefinierten Abmessungen hinzu</em></td></tr></tbody></table><h3 id="absatz-und-uberschriften" tabindex="-1">Absatz und Überschriften <a class="header-anchor" href="#absatz-und-uberschriften" aria-label="Permalink to &quot;Absatz und Überschriften&quot;">​</a></h3><p>Textblöcke bieten <strong>Textgröße</strong> (Überschriftenebene) und <strong>Textausrichtung</strong> — <em>Linksbündig</em>, <em>Zentriert</em>, <em>Rechtsbündig</em>, <em>Blocksatz</em> — sowie <strong>Textfarbe</strong>.</p><p>Leere Blöcke zeigen <em>Leerer Absatz…</em> beziehungsweise <em>Leere Überschrift…</em>.</p><h3 id="layout-blocke" tabindex="-1">Layout-Blöcke <a class="header-anchor" href="#layout-blocke" aria-label="Permalink to &quot;Layout-Blöcke&quot;">​</a></h3><p><strong>Horizontales</strong> und <strong>Vertikales Layout</strong> ordnen enthaltene Blöcke an. Einstellungen unter <strong>Anordnung</strong>:</p><ul><li>Richtung: <em>Nebeneinander</em> / <em>Untereinander</em></li><li>Ausrichtung: <em>Start</em>, <em>Center</em>, <em>End</em>, <em>Oben</em>, <em>Unten</em></li><li><em>Abstand dazwischen</em>, <em>Strecken</em>, <em>Wrap Content</em></li></ul><p>Dazu <strong>Hintergrundfarbe</strong>, <strong>Border radius</strong>, <strong>Breite</strong> und <strong>Höhe</strong>.</p><p><strong>Tab-Layout</strong> und <strong>Stepper-Layout</strong> stellen Unterseiten dar. Ohne Unterseiten erscheint der Hinweis <em>Fügen Sie Seiten hinzu, um sie als Tabs zu sehen</em>.</p><p>→ <a href="/docs/seiten/layout-bloecke">Layout-Blöcke</a></p><hr><h2 id="spezial-blocke" tabindex="-1">Spezial-Blöcke <a class="header-anchor" href="#spezial-blocke" aria-label="Permalink to &quot;Spezial-Blöcke&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Block</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Einbinden</strong></td><td><em>Zeige beliebige externe Inhalte an, z. B. Webseiten oder Videos</em></td></tr><tr><td><strong>Grid Ansicht</strong></td><td><em>Eine Ansicht einbinden, z.B. Kanban, Grid, Kalender, Karte oder Galerie</em></td></tr><tr><td><strong>Flow</strong></td><td><em>Flow einbinden und im Flow-Editor öffnen</em></td></tr><tr><td><strong>Dateiliste</strong></td><td><em>Listenansicht mit Datei-Upload per Drag and Drop</em></td></tr><tr><td><strong>Button</strong></td><td><em>Button um ein Formular oder einen Flow zu starten</em></td></tr><tr><td><strong>QR Code</strong></td><td><em>QR Code für ein Formular oder einen Flow</em></td></tr><tr><td><strong>Zähler</strong></td><td><em>Zähle die Anzahl der Einträge in einer Ansicht</em></td></tr><tr><td><strong>Summenkarte</strong></td><td><em>Summiert die Werte einer numerischen Spalte in einer Ansicht</em></td></tr><tr><td><strong>Donut-Diagramm</strong></td><td><em>Zeigt die Verteilung der Werte einer Einzelauswahl-Spalte</em></td></tr><tr><td><strong>Terminprognose</strong></td><td><em>Vergleicht geplante Termine mit aktuellen und früheren Schätzungen</em></td></tr><tr><td><strong>HTML</strong></td><td><em>Eigenes HTML einbinden oder per KI erstellen</em></td></tr><tr><td><strong>Grid Liste</strong></td><td><em>Erstelle eine Liste basierend auf Einträgen aus einem Grid</em></td></tr></tbody></table><h3 id="grid-ansicht" tabindex="-1">Grid Ansicht <a class="header-anchor" href="#grid-ansicht" aria-label="Permalink to &quot;Grid Ansicht&quot;">​</a></h3><p>Bettet eine bestehende Ansicht in die Seite ein — der wichtigste Block für Portale.</p><p><strong>Einstellungen:</strong></p><table tabindex="0"><thead><tr><th>Einstellung</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Grid Ansicht</strong></td><td>Welche Ansicht eingebettet wird</td></tr><tr><td><strong>Volle Breite anzeigen</strong></td><td>Ansicht über die volle Seitenbreite</td></tr><tr><td><strong>Suche anzeigen</strong></td><td>Suchfeld für Besucher</td></tr><tr><td><strong>Filter anzeigen</strong></td><td>Filter für Besucher</td></tr><tr><td><strong>CSV-Download anzeigen</strong></td><td>Export für Besucher</td></tr><tr><td><strong>Einträge nur lesbar</strong></td><td>Verhindert Bearbeitung</td></tr><tr><td><strong>Detailansicht nicht öffnen</strong></td><td>Klick auf eine Zeile öffnet nichts</td></tr><tr><td><strong>Titel ausblenden</strong></td><td>Blendet den Ansichtstitel aus</td></tr><tr><td><strong>Button Farbe</strong></td><td>Farbe der Bedienelemente</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Zwei Schalter für schreibgeschützte Portale</p><p>Für ein reines Anzeige-Portal reicht <em>Einträge nur lesbar</em> nicht immer aus. Setzen Sie zusätzlich <em>Detailansicht nicht öffnen</em>, sonst gelangen Besucher weiterhin in die Einzelansicht eines Eintrags.</p></div><div class="tip custom-block"><p class="custom-block-title">Filter der Ansicht wirkt mit</p><p>Eingebettet wird die Ansicht samt Filter und ausgeblendeten Spalten. Legen Sie für ein Portal eine eigene Ansicht an, die nur die freizugebenden Daten zeigt, statt eine interne Arbeitsansicht einzubetten.</p></div><h3 id="auswertungsblocke" tabindex="-1">Auswertungsblöcke <a class="header-anchor" href="#auswertungsblocke" aria-label="Permalink to &quot;Auswertungsblöcke&quot;">​</a></h3><p><strong>Zähler</strong> zeigt die Anzahl der Einträge einer Ansicht.</p><p><strong>Summenkarte</strong> summiert eine numerische Spalte. Meldungen:</p><ul><li><em>Diese Ansicht hat keine summierbaren numerischen Spalten</em> — es fehlt eine Spalte vom Typ Zahl, Kommazahl oder Währung</li><li><em>Diese Ansicht hat mehr als {maxRows} Zeilen. Die Summe umfasst nur die ersten {maxRows} Zeilen.</em></li></ul><div class="warning custom-block"><p class="custom-block-title">Summen sind bei großen Ansichten unvollständig</p><p>Ab einer bestimmten Zeilenzahl summiert der Block nur den Anfang der Ansicht. Für belastbare Gesamtsummen ist eine <a href="/docs/ansichten/filtern-sortieren-gruppieren">Gruppierung mit Aggregat</a> oder ein Feld vom Typ <em>Summe berechnen</em> der sichere Weg.</p></div><p><strong>Donut-Diagramm</strong> zeigt die Verteilung über eine Spalte vom Typ <strong>Einzelauswahl</strong>. Ohne eine solche Spalte funktioniert der Block nicht.</p><h3 id="button-und-qr-code" tabindex="-1">Button und QR Code <a class="header-anchor" href="#button-und-qr-code" aria-label="Permalink to &quot;Button und QR Code&quot;">​</a></h3><p>Beide verweisen auf ein Formular oder einen Flow und starten ihn. Der QR-Code-Block eignet sich für Aushänge und gedrucktes Material.</p><h3 id="dateiliste" tabindex="-1">Dateiliste <a class="header-anchor" href="#dateiliste" aria-label="Permalink to &quot;Dateiliste&quot;">​</a></h3><p>Listenansicht mit Drag-&amp;-Drop-Upload. Hinweis in der Ablagefläche: <em>Dateien hier ablegen, um neue Einträge zu erstellen</em>. Rückmeldungen: <em>{count} Datei(en) wurden hochgeladen und gespeichert</em> beziehungsweise <em>… konnten nicht hochgeladen werden</em>.</p><h3 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h3><p>Eigener HTML-Code mit <strong>Live-Vorschau</strong>.</p>',35)),t("ul",null,[e[2]||(e[2]=t("li",null,[t("strong",null,"Mit KI generieren"),n(" — Änderungen beschreiben statt schreiben")],-1)),e[3]||(e[3]=t("li",null,[t("strong",null,"Vorherige HTML-Version wiederherstellen")],-1)),e[4]||(e[4]=t("li",null,[t("strong",null,"Höhe automatisch anpassen")],-1)),t("li",null,[e[0]||(e[0]=n("Vorlagenvariablen mit ",-1)),t("code",null,i(),1),e[1]||(e[1]=n(", Beispiel ",-1)),t("code",null,i(a.variableName),1)])]),e[6]||(e[6]=r('<p>Bei Fehlern erscheint <em>Vorschau-Fehler</em>, bei fehlgeschlagener Erzeugung <em>HTML konnte nicht generiert werden</em>.</p><h3 id="grid-liste" tabindex="-1">Grid Liste <a class="header-anchor" href="#grid-liste" aria-label="Permalink to &quot;Grid Liste&quot;">​</a></h3><p>Erzeugt aus den Einträgen eines Grids eine Liste. Sie wählen das Grid (<em>Grid auswählen</em>) und gestalten einen Vorlagenblock, der je Eintrag wiederholt wird (<em>Listen-Element bearbeiten</em>).</p><h3 id="einbinden" tabindex="-1">Einbinden <a class="header-anchor" href="#einbinden" aria-label="Permalink to &quot;Einbinden&quot;">​</a></h3><p>Bettet externe Inhalte per iframe ein — Webseiten, Videos, Dokumente.</p><h3 id="terminprognose" tabindex="-1">Terminprognose <a class="header-anchor" href="#terminprognose" aria-label="Permalink to &quot;Terminprognose&quot;">​</a></h3><p>Vergleicht geplante Termine mit aktuellen und früheren Schätzungen. Der Anwendungsfall ist in der Oberfläche nicht näher erläutert.</p><hr><h2 id="formularfeld-blocke" tabindex="-1">Formularfeld-Blöcke <a class="header-anchor" href="#formularfeld-blocke" aria-label="Permalink to &quot;Formularfeld-Blöcke&quot;">​</a></h2><p>Dieselben Eingabefelder wie in Formularen, frei auf der Seite platzierbar.</p><table tabindex="0"><thead><tr><th>Block</th><th>Beschreibung in der Oberfläche</th></tr></thead><tbody><tr><td><strong>Einzeiliges Textfeld</strong></td><td><em>Für kurze Eingaben wie Name, Firma oder Betreff</em></td></tr><tr><td><strong>Mehrzeiliges Textfeld</strong></td><td><em>Für längere Eingaben wie Kommentare oder Beschreibungen</em></td></tr><tr><td><strong>Barcode-Scanner</strong></td><td><em>QR-Codes und 2D-Barcodes mit der Kamera scannen</em></td></tr><tr><td><strong>E-Mail</strong></td><td><em>Eine E-Mail Adresse einfügen</em></td></tr><tr><td><strong>Telefon</strong></td><td>–</td></tr><tr><td><strong>Datum</strong></td><td>–</td></tr><tr><td><strong>Datum und Uhrzeit</strong></td><td>–</td></tr><tr><td><strong>Kommazahl</strong></td><td><em>Eine Zahl mit Nachkommastellen einfügen</em></td></tr><tr><td><strong>Zahl</strong></td><td><em>Eine ganze Zahl einfügen</em></td></tr><tr><td><strong>Bewertungsskala</strong></td><td><em>Bewertungen mit Zahlen, Sternen oder Emojis erfassen</em></td></tr><tr><td><strong>Auswahl als Dropdown</strong></td><td><em>Einen Wert aus einem Dropdown-Menü auswählen</em></td></tr><tr><td><strong>Auswahl als Liste</strong></td><td><em>Einen Wert aus einer Liste auswählen</em></td></tr><tr><td><strong>Mehrfachauswahl</strong></td><td><em>Mehrere Werte aus einer Liste auswählen</em></td></tr><tr><td><strong>Häkchen</strong></td><td><em>Fügen Sie eine Checkbox zu Ihrer Seite hinzu</em></td></tr><tr><td><strong>Entscheidung</strong></td><td><em>Zeigt eine Ja/Nein-Entscheidung an und speichert die Auswahl als Wahr/Falsch-Wert</em></td></tr><tr><td><strong>Unterschrift</strong></td><td><em>Unterschrift einfügen</em></td></tr><tr><td><strong>Eintrag</strong></td><td><em>Einen Eintrag aus einem Grid auswählen</em></td></tr><tr><td><strong>Einträge</strong></td><td><em>Mehrere Einträge aus einem Grid auswählen</em></td></tr><tr><td><strong>Anschrift</strong></td><td>–</td></tr><tr><td><strong>Standort</strong></td><td><em>Einen Standort zu Ihrem Formular hinzufügen</em></td></tr><tr><td><strong>URL</strong></td><td><em>Einen Link zu einer Webseite einfügen</em></td></tr><tr><td><strong>Dateien oder Fotos hochladen</strong></td><td><em>Fotos oder Dateien hochladen, auf dem Smartphone auch per Kamera</em></td></tr><tr><td><strong>Währung</strong></td><td>–</td></tr><tr><td><strong>Video</strong></td><td><em>Fügen Sie ein obligatorisches Video zu Ihrem Formular hinzu</em></td></tr><tr><td><strong>Sprachaufnahme</strong></td><td><em>Nehmen Sie eine Sprachaufnahme auf</em></td></tr><tr><td><strong>Video hochladen</strong></td><td><em>Nehmen Sie ein Video auf und laden Sie es hoch</em></td></tr><tr><td><strong>Foto Kamera</strong></td><td><em>Machen Sie ein Foto und laden Sie es hoch</em></td></tr><tr><td><strong>HTML mit Formularfeldern</strong></td><td><em>Eigenes HTML einbinden und Formularfelder per KI hinzufügen</em></td></tr></tbody></table><h3 id="bewertungsskala" tabindex="-1">Bewertungsskala <a class="header-anchor" href="#bewertungsskala" aria-label="Permalink to &quot;Bewertungsskala&quot;">​</a></h3><p>Erfasst Bewertungen als Zahl, mit Sternen oder Emojis als Darstellung.</p><h3 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h3><p>Zeigt eine Ja/Nein-Auswahl als Karten und speichert sie als Wahrheitswert. Deutlicher als ein Häkchen, wenn die Entscheidung bewusst getroffen werden soll.</p><h3 id="aufnahme-blocke" tabindex="-1">Aufnahme-Blöcke <a class="header-anchor" href="#aufnahme-blocke" aria-label="Permalink to &quot;Aufnahme-Blöcke&quot;">​</a></h3><p><strong>Sprachaufnahme</strong>, <strong>Video hochladen</strong> und <strong>Foto Kamera</strong> nehmen direkt über das Gerät auf. Bedienelemente: <em>START</em>, <em>PAUSE</em>, <em>WEITER</em>, <em>Fertig</em>. Ohne Berechtigung erscheint <em>Bitte erlauben Sie den Zugriff auf das Mikrofon</em>.</p><div class="tip custom-block"><p class="custom-block-title">Sprachaufnahme mit Flows kombinieren</p><p>Eine Sprachaufnahme lässt sich im Flow mit dem Schritt <strong>Sprache zu Text</strong> in Text umwandeln. So werden aus gesprochenen Meldungen durchsuchbare Einträge.</p></div><h3 id="html-mit-formularfeldern" tabindex="-1">HTML mit Formularfeldern <a class="header-anchor" href="#html-mit-formularfeldern" aria-label="Permalink to &quot;HTML mit Formularfeldern&quot;">​</a></h3><p>Wie der HTML-Block, aber die enthaltenen Eingabefelder schreiben Daten zurück.</p><div class="warning custom-block"><p class="custom-block-title">Felder brauchen name oder id</p><p>Der Editor warnt: <em>Eingabefelder ohne name oder id werden nicht in die Flow-Payload aufgenommen.</em> Ohne eines der beiden Attribute geht der Wert verloren.</p></div><hr><h2 id="nicht-in-der-auswahl-enthalten" tabindex="-1">Nicht in der Auswahl enthalten <a class="header-anchor" href="#nicht-in-der-auswahl-enthalten" aria-label="Permalink to &quot;Nicht in der Auswahl enthalten&quot;">​</a></h2><p>Einige Blocktypen existieren intern, werden aber nicht angeboten — etwa <strong>Überschrift 4</strong>, <strong>Benutzer</strong>, <strong>Wörterbuch</strong> und <strong>Multitext</strong>. Sie sind kein Bestandteil des Produkts und hier nicht dokumentiert.</p><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/docs/seiten/bloecke">Blockübersicht</a></li><li><a href="/docs/seiten/layout-bloecke">Layout-Blöcke</a></li><li><a href="/docs/seiten/auswertungen">Ansichten und Auswertungen einbetten</a></li></ul>',26))])}const f=d(l,[["render",h]]);export{p as __pageData,f as default};
